mapper.select:
select cu.id, cu.template_id as templateId, ct.coupon_name as couponName, ct.coupon_type as couponType, ct.threshold_amount as thresholdAmount, ct.discount_amount as discountAmount, cu.coupon_status as couponStatus, cu.valid_start_at as validStartAt, cu.valid_end_at as validEndAt from coupon_user cu join coupon_template ct on ct.id = cu.template_id and ct.deleted = 0 where cu.user_id = #{userId} and cu.deleted = 0
and cu.coupon_status = #{status}
and ct.coupon_type = #{type}
order by cu.valid_end_at limit #{offset}, #{size}

select count(*)
from coupon_user cu
join coupon_template ct
  on ct.id = cu.template_id
 and ct.deleted = 0
where cu.user_id = #{userId}
  and cu.deleted = 0

    and cu.coupon_status = #{status}


    and ct.coupon_type = #{type}
